match registry.register_running(preview, caller, join.abort_handle()) {
    RegisterOutcome::Registered(id) => {
        registry.attach_live(id, live);
        if id_tx.send(id).is_err() {
            // Detached task already exited (it never reached the
            // oneshot). Without this branch, a future refactor that
            // wires the gate differently would silently leak the
            // registry slot — the call returned "running" to the
            // model but the job is gone. Be loud now so any future
            // semantic change here surfaces in tests, not in prod.
            warn!(process_id = id, "background task abandoned before handoff");
            return error_output(format!(
                "bash: background task for process {id} exited before it could run — \
                 retry, or remove `background: true` to run inline"
            ));
        }

